sys_script_include.script:
var HSBCTradeCaseUtils = Class.create();
HSBCTradeCaseUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getOutcomesOptions: function() {

        var outcomesArray = [];

        var shortDescription = this.getParameter('sysparm_short_description');
//adding this if condition for Shortdescription Contains Dynamic values(Task Number) & Manual Processing Requirement
		var Shortdesc = gs.getProperty("x_hsb11_hsbc_mss_t.Manual_Processing_Requirement");
		var OutCome = gs.getProperty("x_hsb11_hsbc_mss_t.Exception_manually_resolved");
        if (shortDescription.includes(Shortdesc)) {
            return JSON.stringify(OutCome);
        }
        var grTaskTemplate = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task_template');
        grTaskTemplate.addActiveQuery();
        grTaskTemplate.addQuery('short_description', shortDescription.toString());
        grTaskTemplate.query();


        if (grTaskTemplate.next()) {

            var grOutcomes = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task_outcome_mapping');
            grOutcomes.addQuery('trade_template.sys_id', grTaskTemplate.getUniqueValue());
            grOutcomes.query();

            while (grOutcomes.next()) {
                outcomesArray.push(grOutcomes.getDisplayValue('outcome'));
            }

            var result = outcomesArray.sort().join();

            return JSON.stringify(result);

        }
    },

    type: 'HSBCTradeCaseUtils'
});
